限制動態 HTML 的 TAG
Default options allowedTags: [ &quot;address&quot;, &quot;article&quot;, &quot;aside&quot;, &quot;footer&quot;, &quot;header&quot;, &quot;h1&quot;, &quot;h2&quot;, &quot;h3&quot;, &quot;h4&quot;, &quot;h5&quot;, &quot;h6&quot;, &quot;hgroup&quot;, &quot;main&quot;, &quot;nav&quot;, &quot;section&quot;, &quot;blockquote&quot;, &quot;dd&quot;, &quot;div&quot;, &quot;dl&quot;, &quot;dt&quot;, &quot;figcaption&quot;, &quot;figure&quot;, &quot;hr&quot;, &quot;li&quot;, &quot;main&quot;, &quot;ol&quot;, &quot;p&quot;, &quot;pre&quot;, &quot;ul&quot;, &quot;a&quot;, &quot;abbr&quot;, &quot;b&quot;, &quot;bdi&quot;, &quot;bdo&quot;, &quot;br&quot;, &quot;cite&quot;, &quot;code&quot;, &quot;data&quot;, &quot;dfn&quot;, &quot;em&quot;, &quot;i&quot;, &quot;kbd&quot;, &quot;mark&quot;, &quot;q&quot;, &quot;rb&quot;, &quot;rp&quot;, &quot;rt&quot;, &quot;rtc&quot;, &quot;ruby&quot;, &quot;s&quot;, &quot;samp&quot;, &quot;small&quot;, &quot;span&quot;, &quot;strong&quot;, &quot;sub&quot;, &quot;sup&quot;, &quot;time&quot;, &quot;u&quot;, &quot;var&quot;, &quot;wbr&quot;, &quot;caption&quot;, &quot;col&quot;, &quot;colgroup&quot;, &quot;table&quot;, &quot;tbody&quot;, &quot;td&quot;, &quot;tfoot&quot;, &quot;th&quot;, &quot;thead&quot;, &quot;tr&quot;],disallowedTagsMode: &#x27;discard&#x27;,allowedAttributes: &#123; a: [ &#x27;href&#x27;, &#x27;name&#x27;, &#x27;target&#x27; ], // We don&#x27;t currently allow img itself by default, but // these attributes would make sense if we did. img: [ &#x27;src&#x27;, &#x27;srcset&#x27;, &#x27;alt&#x27;, &#x27;title&#x27;, &#x27;width&#x27;, &#x27;height&#x27;, &#x27;loading&#x27; ]&#125;,// Lots of these won&#x27;t come up by default because we don&#x27;t allow themselfClosing: [ &#x27;img&#x27;, &#x27;br&#x27;, &#x27;hr&#x27;, &#x27;area&#x27;, &#x27;base&#x27;, &#x27;basefont&#x27;, &#x27;input&#x27;, &#x27;link&#x27;, &#x27;meta&#x27; ],// URL schemes we permitallowedSchemes: [ &#x27;http&#x27;, &#x27;https&#x27;, &#x27;ftp&#x27;, &#x27;mailto&#x27;, &#x27;tel&#x27; ],allowedSchemesByTag: &#123;&#125;,allowedSchemesAppliedToAttributes: [ &#x27;href&#x27;, &#x27;src&#x27;, &#x27;cite&#x27; ],allowProtocolRelative: true,enforceHtmlBoundary: false
限制 CSS &amp; Script &amp; iframe 語法
