onst clean = sanitizeHtml(dirty, &#123; allowedTags: [&#x27;p&#x27;], allowedAttributes: &#123; &#x27;p&#x27;: [&quot;style&quot;], &#125;, allowedStyles: &#123; &#x27;*&#x27;: &#123; // Match HEX and RGB &#x27;color&#x27;: [/^#(0x)?[0-9a-f]+$/i, /^rgb\(\s*(\d&#123;1,3&#125;)\s*,\s*(\d&#123;1,3&#125;)\s*,\s*(\d&#123;1,3&#125;)\s*\)$/], &#x27;text-align&#x27;: [/^left$/, /^right$/, /^center$/], // Match any number with px, em, or % &#x27;font-size&#x27;: [/^\d+(?:px|em|%)$/] &#125;, &#x27;p&#x27;: &#123; &#x27;font-size&#x27;: [/^\d+rem$/] &#125; &#125; &#125;);
